import { MagnifyingGlassIcon, XMarkIcon } from "@heroicons/react/24/outline";
import { useState } from "react";
import { Link } from "react-router-dom";
import HistoricalImage from "@/assets/historical-image.png";
import VisualArchivesImage from "@/assets/visual-archives-image.png";
import OralTraditionImage from "@/assets/oral-tradition-image.png";
import LearnYorubaImage from "@/assets/learn-yoruba-image.png";
import { classNames } from "@/utils";

const FeaturedImages = {
  historical: HistoricalImage,
  visual: VisualArchivesImage,
  oral: OralTraditionImage,
  learn: LearnYorubaImage,
};

type QuickLinkCardProps = {
  href: string;
  label: string;
};

const QuickLinkCard = ({ href, label }: QuickLinkCardProps) => {
  return (
    <Link to={href} className="block flex-grow shrink-0 group">
      <div className="p-4 bg-goldcolor rounded-2xl group-hover:bg-goldcolor/90 transition-colors">
        <p className="text-white text-sm sm:text-base font-medium font-nunito capitalize text-center">
          {label}
        </p>
      </div>
    </Link>
  );
};

type ArchiveMiniCardComponentProps = {
  title: string;
  Icon: React.JSX.Element;
  description: string;
};

const ArchiveMiniCardComponent = ({ title, Icon, description }: ArchiveMiniCardComponentProps) => {
  return (
    <div className="p-3 rounded-2xl bg-lightgoldcolorfive flex items-center gap-3">
      <span className="flex items-center justify-center rounded-xl bg-lightgoldcolor h-16 w-16">
        {Icon}
      </span>
      <div className="space">
        <h3 className="font-semibold font-nunito text-base">{title}</h3>
        <p className="font-normal font-nunito text-sm">{description}</p>
      </div>
    </div>
  );
};

type ArchiveCardComponentProps = {
  imageLink: string;
  description?: string;
  title: string;
  otherClasses?: string;
};

const ArchiveCardComponent = ({
  imageLink,
  description,
  title,
  otherClasses,
}: ArchiveCardComponentProps) => {
  return (
    <div className={classNames("bg-lightgoldcolorsix p-4 rounded-xl", otherClasses!)}>
      <header className="min-h-40 overflow-hidden rounded-lg">
        <img src={imageLink} alt={title} className="object-center object-cover h-full w-full" />
      </header>

      <div className="mt-4">
        <h3 className="sm:text-lg font-semibold capitalize font-nunito">{title}</h3>
        {description && <p className="text-sm font-medium font-nunito">{description}</p>}
      </div>
    </div>
  );
};

